#include <LiquidCrystal.h>
#include <math.h>

// =====================================================
// 1. PIN CONFIGURATION
// =====================================================

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int LM35_PIN   = A0;
const int HEATER_PIN = 9;
const int FAN_PIN    = 10;

// =====================================================
// 2. TEMPERATURE SETTINGS
// =====================================================

const double SETPOINT = 25.0;

// Heating hysteresis
const double HEATER_ON_TEMP  = 23.0;
const double HEATER_OFF_TEMP = 25.0;

// Cooling hysteresis
const double FAN_ON_TEMP  = 25.5;
const double FAN_OFF_TEMP = 25.0;

// =====================================================
// 3. MOTOR SETTINGS
// =====================================================

const int MIN_PWM = 120;
const int MAX_PWM = 255;

// =====================================================
// 4. PID PARAMETERS
// =====================================================

double Kp = 45.0;
double Ki = 0.15;
double Kd = 1.5;

double integral = 0.0;
double previousError = 0.0;

// =====================================================
// 5. THERMAL MODEL
// =====================================================

// Approximate simulation parameters.
// These are NOT real greenhouse measurements.

const double HEATING_RATE = 0.20;
const double COOLING_RATE = 0.25;
const double PASSIVE_LOSS = 0.015;

// =====================================================
// 6. TEMPERATURE VARIABLES
// =====================================================

double ambientTemperature = 25.0;
double simulatedTemperature = 25.0;

// =====================================================
// 7. CONTROL VARIABLES
// =====================================================

int heaterPWM = 0;
int fanPWM = 0;

bool heaterEnabled = false;
bool fanEnabled = false;

unsigned long lastControlTime = 0;
unsigned long lastLCDTime = 0;

// =====================================================
// 8. READ LM35
// =====================================================

double readLM35() {

  int sensorValue = analogRead(LM35_PIN);

  double voltage = sensorValue * (5.0 / 1023.0);

  // LM35 output: 10 mV per degree Celsius
  return voltage * 100.0;
}

// =====================================================
// 9. MOTOR PWM
// =====================================================

int calculateMotorPWM(double errorMagnitude) {

  // Proportional power based on distance from target
  double requestedPWM = 45.0 * errorMagnitude;

  requestedPWM = constrain(
    requestedPWM,
    0.0,
    (double)MAX_PWM
  );

  int pwm = (int)requestedPWM;

  // Motor runs at a practical minimum PWM,
  // or it is completely OFF.
  if (pwm > 0 && pwm < MIN_PWM) {
    pwm = MIN_PWM;
  }

  return pwm;
}

// =====================================================
// 10. PID CONTROLLER
// =====================================================

void updateController(double dt) {

  double error = SETPOINT - simulatedTemperature;

  // -----------------------------------------------
  // HEATING MODE
  // -----------------------------------------------

  if (simulatedTemperature <= HEATER_ON_TEMP) {
    heaterEnabled = true;
  }

  if (simulatedTemperature >= HEATER_OFF_TEMP) {
    heaterEnabled = false;
  }

  // -----------------------------------------------
  // COOLING MODE
  // -----------------------------------------------

  if (simulatedTemperature >= FAN_ON_TEMP) {
    fanEnabled = true;
  }

  if (simulatedTemperature <= FAN_OFF_TEMP) {
    fanEnabled = false;
  }

  // -----------------------------------------------
  // NEVER RUN BOTH MOTORS AT ONCE
  // -----------------------------------------------

  if (heaterEnabled) {
    fanEnabled = false;
  }

  if (fanEnabled) {
    heaterEnabled = false;
  }

  // -----------------------------------------------
  // PID CALCULATION
  // -----------------------------------------------

  integral += error * dt;

  integral = constrain(
    integral,
    -30.0,
    30.0
  );

  double derivative = 0.0;

  if (dt > 0.0) {
    derivative = (error - previousError) / dt;
  }

  double pidOutput =
      Kp * error
    + Ki * integral
    + Kd * derivative;

  previousError = error;

  // -----------------------------------------------
  // HEATER OUTPUT
  // -----------------------------------------------

  if (heaterEnabled) {

    double heaterDemand = fabs(pidOutput);

    heaterPWM = calculateMotorPWM(heaterDemand);

    fanPWM = 0;

  }

  // -----------------------------------------------
  // FAN OUTPUT
  // -----------------------------------------------

  else if (fanEnabled) {

    double fanDemand = fabs(pidOutput);

    fanPWM = calculateMotorPWM(fanDemand);

    heaterPWM = 0;

  }

  // -----------------------------------------------
  // BOTH OFF
  // -----------------------------------------------

  else {

    heaterPWM = 0;
    fanPWM = 0;

    // Avoid integral buildup while both are off
    integral = 0.0;
  }

  analogWrite(HEATER_PIN, heaterPWM);
  analogWrite(FAN_PIN, fanPWM);
}

// =====================================================
// 11. SIMULATED GREENHOUSE TEMPERATURE
// =====================================================

void updateTemperatureModel(double dt) {

  double heatingEffect =
      HEATING_RATE * ((double)heaterPWM / 255.0);

  double coolingEffect =
      COOLING_RATE * ((double)fanPWM / 255.0);

  // Heat exchange with the surrounding environment
  double passiveEffect =
      PASSIVE_LOSS *
      (simulatedTemperature - ambientTemperature);

  simulatedTemperature +=
      (
        heatingEffect
        - coolingEffect
        - passiveEffect
      ) * dt;

  simulatedTemperature = constrain(
    simulatedTemperature,
    -20.0,
    100.0
  );
}

// =====================================================
// 12. LCD DISPLAY
// =====================================================

void updateLCD() {

  lcd.setCursor(0, 0);

  lcd.print("Temp:");
  lcd.print(simulatedTemperature, 1);
  lcd.write((byte)223);
  lcd.print("C    ");

  lcd.setCursor(0, 1);

  if (heaterPWM > 0) {

    lcd.print("HEATER PWM:");
    lcd.print(heaterPWM);
    lcd.print("   ");

  }

  else if (fanPWM > 0) {

    lcd.print("FAN PWM:");
    lcd.print(fanPWM);
    lcd.print("      ");

  }

  else {

    lcd.print("TEMP STABLE     ");

  }
}

// =====================================================
// 13. SETUP
// =====================================================

void setup() {

  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);

  lcd.setCursor(0, 0);
  lcd.print("SMART GREENHOUSE");

  lcd.setCursor(0, 1);
  lcd.print("PID CONTROLLER");

  delay(2000);

  // Read the starting temperature from LM35.
  // The thermal model then updates the simulated
  // temperature independently.
  ambientTemperature = readLM35();

  simulatedTemperature = ambientTemperature;

  previousError = SETPOINT - simulatedTemperature;

  lastControlTime = millis();
  lastLCDTime = millis();

  lcd.clear();
}

// =====================================================
// 14. MAIN LOOP
// =====================================================

void loop() {

  unsigned long now = millis();

  // Control update every 100 ms
  if (now - lastControlTime >= 100) {

    double dt =
        (now - lastControlTime) / 1000.0;

    lastControlTime = now;

    // Update temperature first
    updateTemperatureModel(dt);

    // Then update the controller
    updateController(dt);
  }

  // LCD update every 300 ms
  if (now - lastLCDTime >= 300) {

    lastLCDTime = now;

    updateLCD();
  }
}
